import readline from 'node:readline';
const lines=readline.createInterface({input:process.stdin});
lines.on('line',line=>{const req=JSON.parse(line);if(req.id===undefined)return;let result;if(req.method==='initialize')result={protocolVersion:req.params.protocolVersion,capabilities:{tools:{}},serverInfo:{name:'fixture',version:'1.0.0'}};else if(req.method==='tools/list')result={tools:[{name:'echo',description:'Echo text',inputSchema:{type:'object',properties:{text:{type:'string'}},required:['text']}}]};else if(req.method==='tools/call'){process.stdout.write(JSON.stringify({jsonrpc:'2.0',method:'notifications/message',params:{level:'info',data:'private-test-log'}})+'\n');result={content:[{type:'text',text:'echo: '+req.params.arguments.text}]}}else result={};process.stdout.write(JSON.stringify({jsonrpc:'2.0',id:req.id,result})+'\n')});
